const CONTROL_TOOLTIPS={particleSize:"Base thickness of particle strokes before random size variation and speed-based width boosts.",particleSizeRandomNegative:"Maximum negative random size offset applied when a particle is spawned.",particleSizeRandomPositive:"Maximum positive random size offset applied when a particle is spawned.",particleRenderMinSpeed:"Particles below this speed are hidden. Just above this threshold, alpha ramps in smoothly.",particleSpeedAlphaBoost:"How strongly faster particles become brighter. Higher values emphasize fast streaks.",particleDuneAlphaBoost:"How strongly dune bands boost particle alpha. Higher values make particles inside dune ridges brighter.",particleDuneSizeBoost:"How strongly dune bands boost particle stroke size. Higher values make particles inside dune ridges thicker.",particleSpeedWidthBoost:"How strongly faster particles get thicker strokes.",particleRenderFraction:"Global streak density scaler. Lower values reduce accumulated ink while preserving continuity.",particleCount:"Maximum particle budget used by the simulation and adaptive particle count system.",boxCollisionParticipantRatio:"Fraction of particles that participate in poem collider box interactions.",enableAutoRenderScale:"Automatically caps the internal canvas size on very large screens, then CSS stretches it to fill the viewport.",autoRenderScaleThresholdPx:"Maximum internal canvas size before auto render scaling caps it.",edgeRespawnWeightBase:"Base chance weight for edge respawn bins before dune influence is applied.",edgeRespawnWeightStrength:"How strongly dune sampling biases random edge respawn locations.",edgeRespawnWeightExponent:"Contrast of edge respawn weighting. Higher values favor high-weight bins more aggressively.",useWeightedEdgeRespawn:"When enabled, all wrapped particles respawn using weighted edge distribution.",edgeRespawnWeightedMixPercent:"Used only when weighted edge respawn is OFF. Percentage of wraps that still use weighted placement.",enableParticleSeparation:"Enables particle-particle collision solving to prevent heavy overlap and clumping.",particleCollisionRadius:"Distance at which particles begin separating from each other.",particleCollisionStrength:"How strongly overlapping particles are pushed apart.",particleCollisionVelocityDamp:"Velocity damping applied during separation impulses to reduce jitter and rebound.",separationEveryNFrames:"Base interval for separation solves. Higher values reduce CPU cost but allow more temporary overlap.",separationNearBoxRadius:"Activates separation for particles near collider boxes.",separationMinSpeed:"Particles moving slower than this may skip separation unless near a box or recently interacted.",maxSeparationPairsPerTick:"Hard cap on pair solves per update tick to bound worst-case CPU load.",maxSeparationCandidatesPerCell:"Limits neighbor candidates checked per cell in dense regions for performance stability.",qualityTargetFps:"Adaptive-quality target. The system throttles up/down to stay near this framerate.",enableAdaptiveQuality:"Automatically changes quality tier based on sustained frame time.",lockQualityTier:"Freezes the current quality tier so adaptive quality can measure performance without changing budgets.",qualityDecisionWindowMs:"How long performance must stay bad/good before changing quality tier.",qualityCooldownMs:"Minimum delay between tier changes to avoid oscillation.",qualityTransitionMs:"How quickly effective quality values blend to a new tier (higher is smoother/slower).",qualityHudEnabled:"Shows a live on-screen performance HUD with FPS, quality tier, and active budgets.",pauseSimulation:"Pauses the flow simulation loop. The simulation also auto-pauses when the tab is hidden.",enableDuneBands:"Turns dune band modulation on or off while leaving ambient wind and turbulence active.",enableAmbientMotion:"Enables the ambient wind field and all motion forces. Disabling freezes particle movement.",ambientWindDirectionDeg:"Sets the direction the ambient wind force pushes particles, in degrees.",ambientWindStrength:"Overall strength of the ambient wind field.",duneBandRotationDeg:"Rotates the dune band pattern independently from the wind direction, in degrees.",duneBandScale:"Controls the spacing between large dune bands. Lower values create tighter banding.",duneBandOffsetPx:"Shifts the dune band pattern across its own axis without changing angle or scale.",duneAlongWarpScale:"Sets the length scale of the along-wind warp that bends the dune bands.",duneWarpStrength:"How strongly the dune bands are warped and bent.",duneContrast:"Increases or softens contrast between high-wind and low-wind dune bands.",duneDriftSpeed:"How quickly the dune field drifts over time.",microNoiseScale:"Spatial scale of the fine turbulence noise field. Larger values make broader, smoother noise.",microTurbulenceStrength:"Strength of the fine-scale turbulent motion layered on top of the main wind.",windBoostParticleRatio:"Fraction of particles assigned to the boosted subgroup.",windBoostSizeMultiplier:"Size multiplier applied to boosted particles before other width boosts.",windBoostAlphaMultiplier:"Additive alpha applied only to boosted particles.",windBoostMinMultiplier:"Minimum wind-force multiplier for boosted particles.",windBoostMaxMultiplier:"Maximum wind-force multiplier for boosted particles.",windBoostTurbulenceMinMultiplier:"Minimum turbulence multiplier for boosted particles.",windBoostTurbulenceMaxMultiplier:"Maximum turbulence multiplier for boosted particles.",enableBoidFlocking:"Enables boid flocking (separation, alignment, cohesion) for boosted particles.",boidNeighborRadius:"Perception radius for alignment and cohesion. Boosted particles within this distance are flock neighbors.",boidSeparationRadius:"Distance below which boosted particles repel each other to avoid crowding.",boidSeparationStrength:"How strongly boosted particles push apart when closer than the separation radius.",boidAlignmentStrength:"How strongly boosted particles steer to match the average heading of nearby flock members.",boidCohesionStrength:"How strongly boosted particles steer toward the center of mass of nearby flock members.",boidMaxSteerForce:"Caps the magnitude of each individual boid steering vector before combining them.",boidWindBlend:"Blends between boid forces (0) and wind/dune forces (1). 0.5 uses both equally.",boidMaxGroupSize:"Preferred max neighbors. When a boid has more neighbors than this, cohesion flips to dispersal.",boidDispersalStrength:"How strongly boids steer away from overcrowded groups.",enableBoxGlow:"Gives particles near collision boxes a glow — halo in base color, white-hot center.",boxGlowRadius:"How far from a box surface a particle can be and still glow. Intensity fades with distance.",boxGlowHaloSize:"Multiplier for the halo stroke width relative to the normal particle stroke.",boxGlowHaloAlpha:"Peak alpha of the halo glow at full intensity.",boxGlowCoreWhite:"How much the particle core shifts toward the core color at full glow. 0 = no shift, 1 = full core color.",boxGlowCoreDiameter:"Stroke diameter of the glowing core in pixels. Larger values make the core color more visible.",boxGlowFadeDelayMs:"How long a particle holds full glow after leaving the box surface, in milliseconds.",boxGlowFadeDurationMs:"How long the glow takes to fade out after the delay, in milliseconds.",glowBlendOklch:"Uses OkLCh perceptual colour space for the glow blend instead of a plain RGB lerp. Keeps colours vivid and avoids passing through grey or white at the midpoint.",glowBlendChromaFloor:"Minimum chroma (colour vividness) held during the OkLCh glow blend. Higher values prevent the transition from desaturating toward grey at the midpoint.",glowBlendHueShift:"Rotates the glow core hue before blending, in degrees. Shifts which arc of the colour wheel the transition travels along.",boxForceMaxRadius:"Maximum distance from a collider where box influence is allowed to affect particles.",surfaceSlideBand:"Thickness of the near-surface band where particles are encouraged to slide along collider faces.",staticInfluenceForwardDotMin:"Minimum forward alignment required before a moving box starts affecting nearby particles.",backsideDragStrength:"How strongly particles are slowed on the lee side of a moving collider.",scrollFreezeDebounceMs:"Delay in milliseconds before particle movement freezes during manual scroll. Higher values make the freeze less hair-trigger.",scrollFreezeFadeInMs:"Duration in milliseconds for particles to fade back in after scroll interaction ends. 0 makes them reappear instantly.",backgroundFadeOscillationPeriodSec:"How many seconds it takes to complete one full ease-in-out background alpha cycle. Set to 0 to disable."},COLOR_CONTROL_TOOLTIPS={fade:"Background clear or fade color used behind the particles.",particles:"Base particle trail color.",windBoostColor:"Color used for boosted particles instead of the base particle color.",separationZone:"Debug color used for separation-zone visualization.",boxStrokeIdle:"Outline color for collider boxes when idle.",boxStrokeDragged:"Outline color for collider boxes while dragged.",boxGlowCore:"Color that particle cores blend toward when glowing near collision boxes."},COLOR_ALPHA_CONTROL_TOOLTIPS={fade:"Alpha used for the background fade pass. Ignored when transparent trails are enabled.",fadeSecondary:"Secondary background fade alpha used as the other end of the oscillation range.",particles:"Base particle alpha before speed and trail fade adjustments.",particlesSecondary:"Secondary particle alpha used as the other end of the oscillation range.",separationZone:"Opacity of the separation-zone debug overlay.",boxStrokeIdle:"Opacity of idle collider box outlines.",boxStrokeDragged:"Opacity of dragged collider box outlines.",boxGlowCore:"Opacity of the glow core color applied to particles near collision boxes."};